interface Actor {
  id: string;
  role: 'admin' | 'user';
}

function takesActor(a: Actor) {}

// @ts-expect-error: fresh literals reject unknown keys
takesActor({ id: '1', role: 'admin', roel: 'oops' });

const viaVar = { id: '1', role: 'admin' as const, roel: 'oops' };
takesActor(viaVar);

// @ts-expect-error: satisfies preserves the fresh-literal check
const viaSatisfies = { id: '1', role: 'admin', roel: 'oops' } satisfies Actor;
